package com.thenerdcj.gui;import com.thenerdcj.FoliaSkyblock;import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;import org.bukkit.Bukkit;import org.bukkit.Material;import com.thenerdcj.util.MessageUtil;import org.bukkit.entity.Player;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.Inventory;import org.bukkit.inventory.InventoryHolder;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import java.util.Arrays;import java.util.List;public abstract class AbstractGUI implements InventoryHolder{protected final FoliaSkyblock plugin;protected final Player player;protected Inventory inventory;public AbstractGUI(FoliaSkyblock plugin,Player player,String title,int size){this.plugin=plugin;this.player=player;this.inventory=Bukkit.createInventory(this,size,MessageUtil.legacy(title));}public abstract void open();protected void fillWithGlass(){ItemStack glass=createItem(Material.GRAY_STAINED_GLASS_PANE," ");for(int i=0;i<inventory.getSize();i++){if(inventory.getItem(i)==null||inventory.getItem(i).getType()==Material.AIR)inventory.setItem(i,glass);}}protected ItemStack createItem(Material material,String name,String... lore){ItemStack item=new ItemStack(material);ItemMeta meta=item.getItemMeta();if(meta!=null){var ser=LegacyComponentSerializer.legacyAmpersand();meta.displayName(ser.deserialize(name));if(lore.length>0){java.util.List<net.kyori.adventure.text.Component> coloredLore=Arrays.stream(lore).map(ser::deserialize).collect(java.util.stream.Collectors.toList());meta.lore(coloredLore);}item.setItemMeta(meta);}return item;}protected ItemStack createButton(Material material,String name,String... lore){return createItem(material,name,lore);}protected void setItem(int slot,ItemStack item){inventory.setItem(slot,item);} @Override public Inventory getInventory(){return inventory;}public void handleClick(InventoryClickEvent event){event.setCancelled(true);}}
